# final06 · ---- 3-1 «Сад молодильных яблок»: мотылёк раскрывается в свете ЛЮБЫХ двух героев рядом ----
# Было: мотылёк смотрел только на active(0) и active(1) — свет героя первого игрока и героя второго. Зажгли перо Прошка и Потап
# (оба — герои первого игрока) — мотылёк оставался непробиваемым; в одиночке так выходит почти всегда (Q — по кругу всех четверых).
# Стало: считаются все герои со светом в радиусе — чьи бы ни были; оставленный с зажжённым пером тоже светит.
# docs/38 (s1-moth): раскрывается только в свете с двух сторон — два света по разные стороны от мотылька (угол больше ≈ 100°), как воришек загоняют.
rep("e.lp=a.map((h,i)=>heroLight(h)&&!players[i].downed&&hd(h.pos,e.pos)<R&&Math.abs(h.pos.y-e.pos.y)<3);e.both=e.lp[0]&&e.lp[1];",
    "const lh=HEROES.filter(h=>heroLight(h)&&hd(h.pos,e.pos)<R&&Math.abs(h.pos.y-e.pos.y)<3);let opp=false;for(let i=0;i<lh.length&&!opp;i++)for(let j=i+1;j<lh.length;j++){const ax=lh[i].pos.x-e.pos.x,az=lh[i].pos.z-e.pos.z,bx=lh[j].pos.x-e.pos.x,bz=lh[j].pos.z-e.pos.z,la=Math.hypot(ax,az)||1,lb=Math.hypot(bx,bz)||1;if((ax*bx+az*bz)/(la*lb)<-0.2){opp=true;break;}}e.lp=[lh.length>=1,opp];e.both=opp;")
rep("text:pi=>'Мотылёк раскроется, лишь коль оба перья '+K(pi,'item')+' рядом зажжёте.'}",
    "text:pi=>'Мотылёк раскроется лишь в свете с двух сторон: перья '+K(pi,'item')+' — по разные стороны от него.'+(G.solo?'<br>В одиночку: зажги перо, смени героя '+K(pi,'swap')+' — свет у оставленного не гаснет — и зайди с другой стороны.':'')}")
